// Normalize Telegram update shape (n8n can output root fields or under `body`)
// Supports both snake_case and camelCase callback key names.

const root = $json;
const u = root.body ?? root;

const cb = u.callback_query ?? u.callbackQuery ?? null;
const msg = u.message ?? u.edited_message ?? u.editedMessage ?? null;

const chatId = cb?.message?.chat?.id ?? msg?.chat?.id ?? null;
const chat_id_text = chatId === null ? null : String(chatId);
const chat_id_num  = chatId === null ? null : Number(chatId);

const action_raw = String((cb?.data ?? msg?.text ?? '')).trim();
const update_kind = cb ? 'callback' : 'message';
const callback_query_id = cb?.id ?? null;


// clear the keyboard by editing the message text to the same text and setting Reply Markup = None
const callback_chat_id = cb?.message?.chat?.id ?? null
const callback_message_id = cb?.message?.message_id ?? null
const callback_message_text = cb?.message?.text ?? null


function parseAction(s) {
  if (!s) return { action_type: 'invalid' };

  // accept: /start, /start anything, /start@botname
  if (/^\/(start|reset)(\s|$|@)/.test(s)) return { action_type: 'start' };
  if (/^\/reset(\s|$|@)/.test(s)) return { action_type: 'start' };

  if (!s.startsWith('v2|')) return { action_type: 'invalid' };
  const parts = s.split('|');
  if (parts.length < 3) return { action_type: 'invalid' };

  const kind = parts[1];
  const arg  = parts.slice(2).join('|');

  if (kind === 'menu') return { action_type: 'menu', menu_name: arg };
  if (kind === 'nav')  return { action_type: 'nav',  nav_flag: arg };
  if (kind === 'run') {
    if (arg === 'search') return { action_type: 'run', run_name: 'search' };
    return { action_type: 'invalid' };
  }

  if (kind === 'set') {
    const kv = parts[2] ?? '';
    const [key, value] = kv.split('=');
    if (!key || value === undefined) return { action_type: 'invalid' };

    if (key === 'period' && ['today','tomorrow','weekend','week'].includes(value)) {
      return { action_type: 'set', set_key: key, set_value: value };
    }

    if (key === 'theme' && ['all','teatr','film','koncert','spotkanie','warsztat','wystawa','wycieczka','sport','inne'].includes(value)) {
      return { action_type: 'set', set_key: key, set_value: value };
    }

    if (key === 'pay' && ['all','free','paid','unknown'].includes(value)) {
      return { action_type: 'set', set_key: key, set_value: value };
    }

    if (key === 'lr' && ['0','1'].includes(value)) {
      return { action_type: 'set', set_key: key, set_value: value };
    }

    return { action_type: 'invalid' };
  }

  return { action_type: 'invalid' };
}

const parsed = parseAction(action_raw);

return [{
  json: {
    chat_id_text,
    chat_id_num,
    action_raw,
    update_kind,
    callback_query_id,
    callback_chat_id,
    callback_message_id,
    callback_message_text,
    ...parsed,
  }
}];

