// runs per item; it receives the wrapper’s single row
const rowsRaw = $json.rows;
const rows = Array.isArray(rowsRaw) ? rowsRaw : JSON.parse(rowsRaw ?? '[]');

const theme = ($json.theme ?? 'all');
const themeLabelMap = {
  teatr: 'Teatr',
  film: 'Film',
  koncert: 'Koncert',
  spotkanie: 'Spotkanie',
  warsztat: 'Warsztat',
  wystawa: 'Wystawa',
  wycieczka: 'Wycieczka',
  sport: 'Sport',
  inne: 'Inne',
};
const themeLabel = themeLabelMap[theme] ?? '';

function fmtDate(d) {
  if (!d) return '';
  const s = String(d);
  return s.includes('T') ? s.slice(0, 10) : s.slice(0, 10);
}

function escHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escAttr(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const fallbackCategory = (theme && theme !== 'all')
  ? (themeLabel || theme)
  : 'Wszystkie';

const lines = rows.map(r => {
  const date = fmtDate(r.date);

  const catRaw = (r.category_raw ?? '').trim();
  const cat = catRaw || fallbackCategory;

  const title = (r.title_display ?? '').trim() || '—';
  const times = (r.times_text ?? '-').trim() || '-';

  const venueRaw = (r.venue_best ?? r.venue_if_any ?? '').trim();
  const venue = venueRaw || 'Sprawdź miejsce na stronie';

  const payBest = (r.pay_best ?? '').trim();
  const paySuffix = (payBest === 'free') ? '💳 Bezpłatne' : '💳 Sprawdź płatność';

  const urlRaw = (r.primary_url ?? r.url ?? '').trim();
  const linkChunk = urlRaw
    ? `<a href="${escAttr(urlRaw)}">Przejdź do strony</a>`
    : 'Przejdź do strony';

  // Required shape:
  // 📅 YYYY-MM-DD - ➡️ <category>:  <title> - 🕰 ... - 📍 ... - ... - link
  const chunks = [];
  chunks.push(`📅 ${escHtml(date)}`);
  chunks.push(`➡️ ${escHtml(cat)}:  ${escHtml(title)}`);
  chunks.push(`🕰 ${escHtml(times)}`);
  chunks.push(`📍 ${escHtml(venue)}`);
  chunks.push(paySuffix);
  chunks.push(linkChunk);

  return chunks.join(' - ');
}).join('\n\n');

return [{ json: { ...$json, ui_text: lines } }];

